-- Pathway: proposed PostgreSQL initial schema (v1)
-- Based on Team 2 Design Sprint Day 1 user stories and feature list.
-- Figma design link could not be inspected; review fields with the team.
-- Run in an existing PostgreSQL database using psql or pgAdmin.
-- UUIDs generated by PostgreSQL 13+ gen_random_uuid().
BEGIN;

CREATE TABLE users (
    id uuid PRIMARY KEY DEFAULT uuidv7(),
    email VARCHAR(255) NOT NULL UNIQUE,
    display_name VARCHAR(150) NOT NULL,
    role VARCHAR(20) NOT NULL CHECK (role IN ('student','employer','advisor','provider','admin')),
    created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE student_profiles (
    user_id UUID PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,
    major VARCHAR(150),
    degree_level VARCHAR(80),
    graduation_date DATE,
    location VARCHAR(200),
    interests TEXT,
    career_goals TEXT,
    work_experience TEXT,
    preferred_job_type VARCHAR(20) CHECK (preferred_job_type IN ('full_time','part_time','internship')),
    digest_frequency_days INTEGER NOT NULL DEFAULT 14 CHECK (digest_frequency_days BETWEEN 1 AND 365),
    suggestions_per_digest INTEGER NOT NULL DEFAULT 4 CHECK (suggestions_per_digest BETWEEN 0 AND 100)
);

CREATE TABLE companies (
    id uuid PRIMARY KEY DEFAULT uuidv7(),
    name VARCHAR(200) NOT NULL,
    industry VARCHAR(150),
    description TEXT,
    company_values TEXT,
    website TEXT,
    owner_user_id UUID NOT NULL REFERENCES users(id) ON DELETE RESTRICT,
    approval_status VARCHAR(20) NOT NULL DEFAULT 'pending'
        CHECK (approval_status IN ('pending','approved','rejected')),
    approved_by UUID REFERENCES users(id) ON DELETE SET NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE opportunities (
    id uuid PRIMARY KEY DEFAULT uuidv7(),
    company_id UUID NOT NULL REFERENCES companies(id) ON DELETE RESTRICT,
    posted_by UUID NOT NULL REFERENCES users(id) ON DELETE RESTRICT,
    title VARCHAR(200) NOT NULL,
    description TEXT NOT NULL,
    job_type VARCHAR(20) NOT NULL CHECK (job_type IN ('full_time','part_time','internship')),
    field VARCHAR(150),
    degree_level VARCHAR(80),
    location VARCHAR(200),
    status VARCHAR(20) NOT NULL DEFAULT 'draft'
        CHECK (status IN ('draft','open','closed')),
    application_deadline DATE,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE applications (
    id uuid PRIMARY KEY DEFAULT uuidv7(),
    student_id UUID NOT NULL REFERENCES student_profiles(user_id) ON DELETE CASCADE,
    opportunity_id UUID NOT NULL REFERENCES opportunities(id) ON DELETE RESTRICT,
    status VARCHAR(25) NOT NULL DEFAULT 'submitted'
        CHECK (status IN ('submitted','reviewing','interview','offered','accepted','rejected','withdrawn')),
    applied_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    UNIQUE (student_id, opportunity_id)
);

CREATE TABLE skills (
    id uuid PRIMARY KEY DEFAULT uuidv7(),
    name VARCHAR(150) NOT NULL UNIQUE,
    skill_type VARCHAR(10) NOT NULL CHECK (skill_type IN ('hard','soft'))
);

CREATE TABLE student_skills (
    student_id UUID NOT NULL REFERENCES student_profiles(user_id) ON DELETE CASCADE,
    skill_id BIGINT NOT NULL REFERENCES skills(id) ON DELETE CASCADE,
    proficiency VARCHAR(20) CHECK (proficiency IN ('beginner','intermediate','advanced')),
    evidence_url TEXT,
    verified_at TIMESTAMPTZ,
    PRIMARY KEY (student_id, skill_id)
);

CREATE TABLE opportunity_skills (
    opportunity_id UUID NOT NULL REFERENCES opportunities(id) ON DELETE CASCADE,
    skill_id BIGINT NOT NULL REFERENCES skills(id) ON DELETE RESTRICT,
    required BOOLEAN NOT NULL DEFAULT TRUE,
    PRIMARY KEY (opportunity_id, skill_id)
);

CREATE TABLE certifications (
    id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    name VARCHAR(200) NOT NULL UNIQUE,
    issuing_organization VARCHAR(200)
);

CREATE TABLE student_certifications (
    id uuid PRIMARY KEY DEFAULT uuidv7(),
    student_id UUID NOT NULL REFERENCES student_profiles(user_id) ON DELETE CASCADE,
    certification_id BIGINT NOT NULL REFERENCES certifications(id) ON DELETE RESTRICT,
    evidence_url TEXT,
    earned_on DATE,
    expires_on DATE,
    verified_by UUID REFERENCES users(id) ON DELETE SET NULL,
    verified_at TIMESTAMPTZ,
    CHECK (expires_on IS NULL OR earned_on IS NULL OR expires_on >= earned_on),
    CHECK (verified_at IS NULL OR verified_by IS NOT NULL)
);

CREATE TABLE courses (
    id uuid PRIMARY KEY DEFAULT uuidv7(),
    provider_user_id UUID NOT NULL REFERENCES users(id) ON DELETE RESTRICT,
    title VARCHAR(200) NOT NULL,
    description TEXT,
    course_url TEXT,
    certification_id BIGINT REFERENCES certifications(id) ON DELETE SET NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE course_skills (
    course_id UUID NOT NULL REFERENCES courses(id) ON DELETE CASCADE,
    skill_id BIGINT NOT NULL REFERENCES skills(id) ON DELETE RESTRICT,
    PRIMARY KEY (course_id, skill_id)
);

CREATE TABLE events (
    id uuid PRIMARY KEY DEFAULT uuidv7(),
    created_by UUID NOT NULL REFERENCES users(id) ON DELETE RESTRICT,
    company_id UUID REFERENCES companies(id) ON DELETE SET NULL,
    title VARCHAR(200) NOT NULL,
    event_type VARCHAR(30) NOT NULL CHECK (event_type IN ('career_fair','campus_event','employer_booth','other')),
    location VARCHAR(200),
    starts_at TIMESTAMPTZ NOT NULL,
    ends_at TIMESTAMPTZ NOT NULL,
    CHECK (ends_at > starts_at)
);

CREATE TABLE notifications (
    id uuid PRIMARY KEY DEFAULT uuidv7(),
    recipient_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    application_id UUID REFERENCES applications(id) ON DELETE SET NULL,
    message TEXT NOT NULL,
    is_read BOOLEAN NOT NULL DEFAULT FALSE,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE messages (
    id uuid PRIMARY KEY DEFAULT uuidv7(),
    sender_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    recipient_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    body TEXT NOT NULL CHECK (length(trim(body)) > 0),
    sent_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    CHECK (sender_id <> recipient_id)
);

CREATE INDEX idx_opportunities_search ON opportunities(status, job_type, location);
CREATE INDEX idx_opportunities_company ON opportunities(company_id);
CREATE INDEX idx_applications_student ON applications(student_id, applied_at DESC);
CREATE INDEX idx_applications_opportunity ON applications(opportunity_id, status);
CREATE INDEX idx_student_skills_skill ON student_skills(skill_id);
CREATE INDEX idx_opportunity_skills_skill ON opportunity_skills(skill_id);
CREATE INDEX idx_course_skills_skill ON course_skills(skill_id);
CREATE INDEX idx_student_certifications_student ON student_certifications(student_id);
CREATE INDEX idx_events_start ON events(starts_at);
CREATE INDEX idx_notifications_unread ON notifications(recipient_id, is_read, created_at DESC);
CREATE INDEX idx_messages_recipient ON messages(recipient_id, sent_at DESC);

COMMIT;
